const express = require('express');
const fs = require('fs');
const path = require('path');
const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, WidthType,
        BorderStyle, ShadingType, AlignmentType, VerticalAlign, HeightRule, PageBreak,
        Header, ImageRun, PageOrientation } = require('docx');
const app = express();

app.use(express.json({ limit: '20mb' }));
app.use(express.static(__dirname));

/* ============================================================
   ARMAZENAMENTO
   - Se a variável de ambiente DATABASE_URL existir  -> PostgreSQL
     (durável e compartilhado entre TODOS os computadores).
   - Senão -> arquivo data.json em DATA_DIR (ou na pasta do app).
     Use DATA_DIR para apontar a um disco persistente (NAS/Render Disk).
   ============================================================ */
const DATA_DIR  = process.env.DATA_DIR || __dirname;
const DATA_FILE = path.join(DATA_DIR, 'data.json');

let pool = null;

async function initDb() {
  if (!process.env.DATABASE_URL) return;            // sem banco -> usa arquivo
  const { Pool } = require('pg');
  pool = new Pool({
    connectionString: process.env.DATABASE_URL,
    ssl: process.env.PGSSL === 'disable' ? false : { rejectUnauthorized: false }
  });
  await pool.query('CREATE TABLE IF NOT EXISTS app_state (id INT PRIMARY KEY, data JSONB, updated_at TIMESTAMPTZ DEFAULT now())');
}

async function readData() {
  if (pool) {
    const r = await pool.query('SELECT data FROM app_state WHERE id = 1');
    return r.rows.length ? r.rows[0].data : null;
  }
  if (fs.existsSync(DATA_FILE)) return JSON.parse(fs.readFileSync(DATA_FILE, 'utf8'));
  return null;
}

async function writeData(obj) {
  if (pool) {
    await pool.query(
      `INSERT INTO app_state (id, data, updated_at) VALUES (1, $1::jsonb, now())
       ON CONFLICT (id) DO UPDATE SET data = $1::jsonb, updated_at = now()`,
      [JSON.stringify(obj)]
    );
    return;
  }
  fs.writeFileSync(DATA_FILE, JSON.stringify(obj));
}

/* ============================================================
   GANGWAY VISITORS RECORD BOOK (.docx) — gerado a partir do
   template OSM Thome (A4 paisagem, cabeçalho azul repetido,
   10 nomes por página, "Mandatory Check" a cada 25, Date/Time On
   em branco, mínimo de 10 páginas).
   ============================================================ */
const OSM_LOGO_B64 = "";
const logoBuf = Buffer.from(OSM_LOGO_B64, 'base64');
const COLW = [2971,2412,991,1560,1560,2976,1560,1699];
const TABLEW = COLW.reduce((a,b)=>a+b,0);
const HDR = ["Visitor\u2019s Name","Visitor\u2019s Company buisness onboard","Visitor`s Pass No.","Date / Time On","Personal belongings checked Yes/No","Visitor\u2019s Signature","Date / Time Off","Duty Crew Signature"];
const BRD = { style: BorderStyle.SINGLE, size: 4, color: "000000" };
const CB  = { top:BRD, bottom:BRD, left:BRD, right:BRD };
const NB  = { top:{style:BorderStyle.NONE}, bottom:{style:BorderStyle.NONE}, left:{style:BorderStyle.NONE}, right:{style:BorderStyle.NONE} };
const grun = (t,o={}) => new TextRun({ text:t, font:o.font||"Times New Roman", size:o.size||24, bold:!!o.bold });
const gpar = (t,o={}) => new Paragraph({ alignment:o.align||AlignmentType.LEFT, spacing:{after:0}, children: t===""?[]:[grun(t,o)] });

function gHeaderRow() {
  return new TableRow({ tableHeader:true, height:{value:1319,rule:HeightRule.ATLEAST},
    children: COLW.map((w,i)=> new TableCell({ width:{size:w,type:WidthType.DXA}, borders:CB, verticalAlign:VerticalAlign.CENTER,
      shading:{type:ShadingType.CLEAR,fill:"8EAADB",color:"auto"}, margins:{top:20,bottom:20,left:60,right:60},
      children:[ new Paragraph({ alignment:AlignmentType.CENTER, spacing:{after:0}, children:[grun(HDR[i],{font:"Arial",size:20,bold:true})] }) ] })) });
}
function gDataRow(person,num) {
  const name = person ? (person.name||"") : "";
  const company = person ? (person.company||"") : "";
  const mand = (num % 25 === 0) ? "Mandatory Check" : "";
  const C = (i,children,valign) => new TableCell({ width:{size:COLW[i],type:WidthType.DXA}, borders:CB,
    verticalAlign:valign||VerticalAlign.CENTER, margins:{top:30,bottom:30,left:60,right:60}, children });
  return new TableRow({ height:{value:671,rule:HeightRule.ATLEAST}, children:[
    C(0,[gpar(name)],VerticalAlign.TOP),
    C(1,[gpar(company,{align:AlignmentType.CENTER})]),
    C(2,[gpar("")]),
    C(3,[gpar("____________",{size:20}), gpar("Time:",{size:20})]),
    C(4,[ mand ? new Paragraph({alignment:AlignmentType.CENTER,spacing:{after:0},children:[grun(mand,{font:"Arial",size:20,bold:true})]}) : gpar("") ]),
    C(5,[gpar("")]),
    C(6,[gpar("")]),
    C(7,[gpar("")]),
  ]});
}
function gTable(people,pageIndex) {
  const PER=10, rows=[gHeaderRow()];
  for (let r=0;r<PER;r++){ const idx=pageIndex*PER+r; rows.push(gDataRow(people[idx],idx+1)); }
  return new Table({ width:{size:TABLEW,type:WidthType.DXA}, columnWidths:COLW.slice(), rows });
}
function gSectionHeader() {
  return new Header({ children:[
    new Table({ width:{size:TABLEW,type:WidthType.DXA}, columnWidths:[3200,TABLEW-3200], borders:NB, rows:[
      new TableRow({ children:[
        new TableCell({ width:{size:3200,type:WidthType.DXA}, borders:NB, verticalAlign:VerticalAlign.CENTER,
          children:[ new Paragraph({ spacing:{after:0}, children:[ new ImageRun({ type:"jpg", data:logoBuf, transformation:{width:165,height:40} }) ] }) ] }),
        new TableCell({ width:{size:TABLEW-3200,type:WidthType.DXA}, borders:NB, verticalAlign:VerticalAlign.CENTER, children:[
          new Paragraph({ alignment:AlignmentType.CENTER, spacing:{after:0}, children:[grun("Gangway Visitors Record Book",{font:"Arial",size:34,bold:true})] }),
          new Paragraph({ alignment:AlignmentType.CENTER, spacing:{after:0}, children:[grun("Marsec level 1",{font:"Arial",size:24})] }),
        ]}),
      ]})
    ]})
  ]});
}
function buildGangwayDocx(people) {
  people = Array.isArray(people) ? people : [];
  const PER=10, nPages=Math.max(10, Math.ceil(people.length/PER));
  const body=[];
  for (let p=0;p<nPages;p++){
    if (p>0) body.push(new Paragraph({ spacing:{after:0}, children:[new PageBreak()] }));
    body.push(gTable(people,p));
  }
  return new Document({
    sections:[{
      properties:{ page:{ size:{ width:11906, height:16838, orientation:PageOrientation.LANDSCAPE },
        margin:{ top:1380, right:283, bottom:280, left:708, header:242, footer:0 } } },
      headers:{ default:gSectionHeader() },
      children:body
    }]
  });
}

app.get('/api/health', (req, res) =>
  res.json({ ok: true, storage: pool ? 'postgres' : 'file', version: 'v8.5' })
);

app.get('/api/data', async (req, res) => {
  try { res.json(await readData()); }
  catch (e) { console.error('GET /api/data', e); res.status(500).json({ error: e.message }); }
});

app.post('/api/data', async (req, res) => {
  /* Merge-preserve: a browser running an older cached index.html posts the
     state WITHOUT newer keys (heliDays, portAct, ...). A plain overwrite
     would silently wipe them for everyone. Keys present in the payload
     always win (deliberate clears still work — current clients always send
     their keys); keys absent are preserved from what is already stored. */
  try {
    const incoming = (req.body && typeof req.body === 'object') ? req.body : {};
    let existing = null;
    try { existing = await readData(); } catch (_) { existing = null; }
    const merged = Object.assign({}, (existing && typeof existing === 'object') ? existing : {}, incoming);
    await writeData(merged);
    res.json({ ok: true });
  }
  catch (e) { console.error('POST /api/data', e); res.status(500).json({ error: e.message }); }
});

app.post('/api/gangway', async (req, res) => {
  try {
    const people = (req.body && Array.isArray(req.body.people)) ? req.body.people : [];
    const buffer = await Packer.toBuffer(buildGangwayDocx(people));
    res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document');
    res.setHeader('Content-Disposition', 'attachment; filename="Gangway_Visitors_Genesis.docx"');
    res.send(buffer);
  } catch (e) { console.error('POST /api/gangway', e); res.status(500).json({ error: e.message }); }
});


/* ============================================================
   PORT ACTIVITIES — Daily Report (.pptx) — OSM Thome template
   ============================================================ */
const PptxGenJS = require('pptxgenjs');
const PA_LOGO = 'data:image/png;base64,';
const PA_FOOTER = 'data:image/png;base64,';
/* ============================================================
   PORT CALL — Daily Report slide generator (PptxGenJS)
   Replicates the OSM Thome "Relatório Diário" template:
   13.33 x 7.5 in, header with logo + report number + date,
   section bands, table header row, one striped row per activity
   with a progress bar and a coloured status badge.
   Overflows onto extra slides automatically.
   ============================================================ */


// ---- palette pulled straight from the reference slide ----
const CLR = {
  titleNavy : '2C2849',
  reportNo  : 'FF0000',
  company   : '5A93C9',
  section   : '1AADE3',
  headerBand: 'F0F5FA',
  headerTxt : '5A6473',
  rowLine   : 'E4EAF0',
  track     : 'E9EEF3',
  text      : '2A2A33',
  sub       : '6A7480',
  progFill  : { DONE:'86C79A', DOING:'E8B87A', 'TO DO':'C3CDD8', CANCELADO:'D48A8A' }
};
const BADGE = {
  DONE      : { fill:'86C79A', font:'FFFFFF' },
  DOING     : { fill:'E8B87A', font:'FFFFFF' },
  'TO DO'   : { fill:'C3CDD8', font:'FFFFFF' },
  CANCELADO : { fill:'D48A8A', font:'FFFFFF' }
};

// column geometry (inches) — matches the template
const COL = {
  act:   { x:0.15, w:5.15 },
  comp:  { x:5.35, w:1.70 },
  start: { x:7.10, w:1.15 },
  end:   { x:8.25, w:1.15 },
  dur:   { x:9.40, w:0.80 },
  prog:  { x:10.20,w:1.35 },
  status:{ x:11.65,w:0.80 }
};
const LEFT = 0.12, FULLW = 12.78;
const ROW_H = 0.185, HDR_H = 0.20, SEC_H = 0.30;
const TOP_START = 1.05, BOTTOM = 7.00; /* footer logo starts at y=7.05 */

function esc(s){ return (s==null?'':String(s)); }

function badgeOf(status){
  const s=(status||'').toUpperCase().trim();
  return BADGE[s] ? s : 'TO DO';
}

function drawHeader(slide, pptx, meta, assets){
  assets=assets||{};
  slide.addText('GÊNESIS I', { x:1.15, y:0.28, w:1.7, h:0.4, fontSize:15, bold:true, color:'7FA9CE', valign:'middle', fontFace:'Calibri' });
  if (assets.logo) slide.addImage({ data:assets.logo, x:2.40, y:0.19, w:0.68, h:0.68 });
  slide.addText('OSM Thome', { x:3.13, y:0.36, w:1.8, h:0.4, fontSize:15, bold:true, color:CLR.titleNavy, valign:'middle', fontFace:'Calibri' });
  slide.addText([
    { text:'Relatório Diário #', options:{ color:CLR.titleNavy } },
    { text:esc(meta.reportNo||'xxx'), options:{ color:CLR.reportNo } }
  ], { x:4.62, y:0.24, w:4.0, h:0.5, fontSize:22, bold:true, valign:'middle', fontFace:'Calibri' });
  // port label (centre-right)
  slide.addText(esc(meta.port||'AÇU PORT - RJ'), { x:8.7, y:0.30, w:2.2, h:0.4, fontSize:13, color:'2A2A33', valign:'middle', align:'left', fontFace:'Calibri' });
  slide.addText(esc(meta.dateLabel||''), { x:11.15, y:0.30, w:2.0, h:0.4, fontSize:14, bold:true, color:CLR.reportNo, align:'left', valign:'middle', fontFace:'Calibri' });
  slide.addShape(pptx.ShapeType.line, { x:0.45, y:0.92, w:12.43, h:0, line:{ color:'D8DEE6', width:1 } });
  // PRIO footer logo bottom-right
  if (assets.footer) slide.addImage({ data:assets.footer, x:11.76, y:7.05, w:1.38, h:0.26 });
}

function drawTableHeader(slide, y){
  slide.addShape('rect', { x:LEFT, y:y, w:FULLW, h:HDR_H, fill:{ color:CLR.headerBand }, line:{ type:'none' } });
  const cells=[['Atividade',COL.act],['Empresa / Resp.',COL.comp],['Início',COL.start],['Término',COL.end],['Duração',COL.dur],['Progresso',COL.prog],['Status',COL.status]];
  cells.forEach(([label,c])=>{
    slide.addText(label, { x:c.x, y:y, w:c.w, h:HDR_H, fontSize:8, bold:true, color:CLR.headerTxt, valign:'middle', fontFace:'Calibri' });
  });
  return y+HDR_H;
}

function drawSectionTitle(slide, y, title){
  slide.addText(esc(title).toUpperCase(), { x:0.15, y:y, w:8, h:SEC_H, fontSize:11, bold:true, color:CLR.section, valign:'middle', fontFace:'Calibri' });
  return y+SEC_H;
}

function drawRow(slide, pptx, y, a, idx){
  if (idx % 2 === 1) slide.addShape('rect', { x:LEFT, y:y, w:FULLW, h:ROW_H, fill:{ color:'FAFBFD' }, line:{ type:'none' } });
  slide.addShape('rect', { x:LEFT, y:y+ROW_H, w:FULLW, h:0.006, fill:{ color:CLR.rowLine }, line:{ type:'none' } });

  slide.addText(esc(a.activity), { x:COL.act.x, y:y, w:COL.act.w, h:ROW_H, fontSize:8, color:CLR.text, valign:'middle', fontFace:'Calibri', fit:'shrink' });
  slide.addText(esc(a.company), { x:COL.comp.x, y:y, w:COL.comp.w, h:ROW_H, fontSize:8, bold:true, color:CLR.company, valign:'middle', fontFace:'Calibri', fit:'shrink' });
  slide.addText(esc(a.start||'—'), { x:COL.start.x, y:y, w:COL.start.w, h:ROW_H, fontSize:7.5, color:CLR.sub, valign:'middle', fontFace:'Calibri' });
  slide.addText(esc(a.end||'—'), { x:COL.end.x, y:y, w:COL.end.w, h:ROW_H, fontSize:7.5, color:CLR.sub, valign:'middle', fontFace:'Calibri' });
  slide.addText(esc(a.duration||'—'), { x:COL.dur.x, y:y, w:COL.dur.w, h:ROW_H, fontSize:7.5, color:CLR.sub, valign:'middle', fontFace:'Calibri' });

  // progress bar — partial progress uses a shorter track with the % label
  // beside it (like the original template); 0% and 100% use the full track
  const badge = badgeOf(a.status);
  const pct = Math.max(0, Math.min(100, +a.progress||0));
  const barY=y+ROW_H/2-0.045, barX=COL.prog.x;
  const partial = (pct>0 && pct<100);
  const barW = partial ? 1.00 : 1.25;
  slide.addShape('rect', { x:barX, y:barY, w:barW, h:0.09, fill:{ color:CLR.track }, line:{ type:'none' }, rectRadius:0.02 });
  if (pct>0){
    const fillClr = CLR.progFill[badge] || '86C79A';
    slide.addShape('rect', { x:barX, y:barY, w:barW*pct/100, h:0.09, fill:{ color:fillClr }, line:{ type:'none' }, rectRadius:0.02 });
  }
  if (partial) slide.addText(pct+'%', { x:barX+1.02, y:y, w:0.40, h:ROW_H, fontSize:6.5, bold:true, color:CLR.progFill[badge]||CLR.sub, valign:'middle', align:'left', fontFace:'Calibri' });

  // status badge
  const b=BADGE[badge];
  const bw = badge==='CANCELADO' ? 1.05 : 0.80;
  slide.addText(badge, { x:COL.status.x, y:y+0.01, w:bw, h:0.17, fontSize: badge==='CANCELADO'?5.5:6.5, bold:true, color:b.font, align:'center', valign:'middle', fill:{ color:b.fill }, rectRadius:0.06, fontFace:'Calibri', shape:'roundRect' });

  return y+ROW_H;
}

/* activities: [{section, activity, company, start, end, duration, progress, status}]
   meta: {reportNo, dateLabel, vessel}
   Groups by section (preserving first-seen order), lays rows out,
   breaks to a new slide when the page fills. */
function buildPptx(activities, meta, assets){
  const pptx = new PptxGenJS();
  pptx.defineLayout({ name:'WIDE', width:13.33, height:7.5 });
  pptx.layout='WIDE';

  // group by section in first-seen order
  const order=[]; const groups={};
  (activities||[]).forEach(a=>{
    const sec=a.section||'GERAL';
    if(!groups[sec]){ groups[sec]=[]; order.push(sec); }
    groups[sec].push(a);
  });

  let slide=pptx.addSlide();
  drawHeader(slide, pptx, meta, assets);
  let y=TOP_START;
  let rowIdx=0;

  function newSlide(){
    slide=pptx.addSlide();
    drawHeader(slide, pptx, meta, assets);
    y=TOP_START;
  }

  order.forEach(sec=>{
    // section title + header need at least ~3 rows of room; else new slide
    if (y + SEC_H + HDR_H + ROW_H*2 > BOTTOM) newSlide();
    y=drawSectionTitle(slide, y, sec);
    y=drawTableHeader(slide, y);
    rowIdx=0;
    groups[sec].forEach(a=>{
      if (y + ROW_H > BOTTOM){
        newSlide();
        y=drawSectionTitle(slide, y, sec+' (cont.)');
        y=drawTableHeader(slide, y);
        rowIdx=0;
      }
      y=drawRow(slide, pptx, y, a, rowIdx++);
    });
    y+=0.10; // gap between sections
  });

  return pptx;
}

app.post('/api/portact-pptx', async (req, res) => {
  try {
    const b = req.body || {};
    const activities = Array.isArray(b.activities) ? b.activities : [];
    const meta = b.meta || {};
    const pptx = buildPptx(activities, meta, { logo: PA_LOGO, footer: PA_FOOTER });
    const buffer = await pptx.write('nodebuffer');
    res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.presentationml.presentation');
    res.setHeader('Content-Disposition', 'attachment; filename="Relatorio_Diario_Genesis.pptx"');
    res.send(buffer);
  } catch (e) { console.error('POST /api/portact-pptx', e); res.status(500).json({ error: e.message }); }
});

app.get('*', (req, res) => res.sendFile(path.join(__dirname, 'index.html')));

const PORT = process.env.PORT || 3000;
initDb()
  .catch(e => { console.error('Falha ao iniciar o banco, usando arquivo:', e.message); pool = null; })
  .finally(() => app.listen(PORT, () =>
    console.log(`Genesis I na porta ${PORT} — armazenamento: ${pool ? 'PostgreSQL' : ('arquivo (' + DATA_FILE + ')')}`)
  ));
